    public List<PolicyCoverage> testGetAll() throws Throwable {
    LOGGER.info( "PolicyCoverageTest:testGetAll() - Retrieving Collection of PolicyCoverages:" );

    StringBuilder msg = new StringBuilder( "-- Failed to get all PolicyCoverage : " );
    List<PolicyCoverage> collection  = null;

    try {
        // call the static get method on the PolicyCoverageService
        collection = service.getAllPolicyCoverage();

        if ( collection == null || collection.size() == 0 ) {
            LOGGER.warning( unexpectedErrorMsg );
            LOGGER.warning( "-- " + msg.toString() + " Empty collection returned."  );
        }
        else {
            // Now print out the values
            PolicyCoverage currEntity  = null;
            Iterator<PolicyCoverage> iter = collection.iterator();

            while( iter.hasNext() ) {
                // Retrieve the entity
                currEntity = iter.next();

                assertNotNull( currEntity,"-- null value object in Collection." );
                assertNotNull( currEntity.getPolicyCoverageId(), "-- value object in Collection has a null primary key" );

                LOGGER.info( " - " + currEntity.toString() );
            }
        }
    }
    catch ( Throwable e ){
        LOGGER.warning( unexpectedErrorMsg );
        LOGGER.warning( msg.toString() );

        throw e;
    }

    return( collection );
}

